class Solution:
    def minimumCost(self, target: str, words: List[str], costs: List[int]) -> int:
        n = len(target)
        ch = [{}]
        cost = [float('inf')]
        for w, c in zip(words, costs):
            node = 0
            for x in w:
                if x not in ch[node]:
                    ch.append({}); cost.append(float('inf'))
                    ch[node][x] = len(ch) - 1
                node = ch[node][x]
            cost[node] = min(cost[node], c)
        dp = [float('inf')] * (n + 1)
        dp[0] = 0
        for i in range(n):
            if dp[i] == float('inf'): continue
            node = 0
            for j in range(i, n):
                if target[j] not in ch[node]: break
                node = ch[node][target[j]]
                if cost[node] < float('inf'):
                    if dp[i] + cost[node] < dp[j + 1]:
                        dp[j + 1] = dp[i] + cost[node]
        return dp[n] if dp[n] < float('inf') else -1

