class Solution {
public:
    int minimumCost(string target, vector<string>& words, vector<int>& costs) {
        int n = target.size();
        vector<array<int,26>> ch(1, {});
        for (auto& a : ch[0]) a.fill(-1);
        vector<int> cost(1, INT_MAX);
        auto newNode = [&]() {
            ch.push_back({}); for (auto& a : ch.back()) a.fill(-1);
            cost.push_back(INT_MAX);
            return (int)ch.size() - 1;
        };
        for (size_t wi = 0; wi < words.size(); wi++) {
            int node = 0;
            for (char c : words[wi]) {
                int b = c - 'a';
                if (ch[node][b] < 0) ch[node][b] = newNode();
                node = ch[node][b];
            }
            cost[node] = min(cost[node], costs[wi]);
        }
        vector<long long> dp(n + 1, LLONG_MAX);
        dp[0] = 0;
        for (int i = 0; i < n; i++) {
            if (dp[i] == LLONG_MAX) continue;
            int node = 0;
            for (int j = i; j < n; j++) {
                int b = target[j] - 'a';
                if (ch[node][b] < 0) break;
                node = ch[node][b];
                if (cost[node] < INT_MAX)
                    dp[j + 1] = min(dp[j + 1], dp[i] + cost[node]);
            }
        }
        return dp[n] == LLONG_MAX ? -1 : (int)dp[n];
    }
};

