class Solution {
    public int minimumCost(String target, String[] words, int[] costs) {
        int n = target.length();
        List<int[]> ch = new ArrayList<>();
        ch.add(new int[26]); Arrays.fill(ch.get(0), -1);
        List<Integer> cost = new ArrayList<>(List.of(Integer.MAX_VALUE));
        for (int wi = 0; wi < words.length; wi++) {
            int node = 0;
            for (char c : words[wi].toCharArray()) {
                int b = c - 'a';
                if (ch.get(node)[b] < 0) {
                    int[] nx = new int[26]; Arrays.fill(nx, -1);
                    ch.add(nx); cost.add(Integer.MAX_VALUE);
                    ch.get(node)[b] = ch.size() - 1;
                }
                node = ch.get(node)[b];
            }
            cost.set(node, Math.min(cost.get(node), costs[wi]));
        }
        long[] dp = new long[n + 1];
        Arrays.fill(dp, Long.MAX_VALUE);
        dp[0] = 0;
        for (int i = 0; i < n; i++) {
            if (dp[i] == Long.MAX_VALUE) continue;
            int node = 0;
            for (int j = i; j < n; j++) {
                int b = target.charAt(j) - 'a';
                if (ch.get(node)[b] < 0) break;
                node = ch.get(node)[b];
                if (cost.get(node) < Integer.MAX_VALUE)
                    dp[j + 1] = Math.min(dp[j + 1], dp[i] + cost.get(node));
            }
        }
        return dp[n] == Long.MAX_VALUE ? -1 : (int) dp[n];
    }
}

