var minimumCost = function(target, words, costs) {
    const n = target.length;
    const ch = [new Map()], cost = [Infinity];
    for (let wi = 0; wi < words.length; wi++) {
        let node = 0;
        for (const c of words[wi]) {
            if (!ch[node].has(c)) {
                ch.push(new Map()); cost.push(Infinity);
                ch[node].set(c, ch.length - 1);
            }
            node = ch[node].get(c);
        }
        cost[node] = Math.min(cost[node], costs[wi]);
    }
    const dp = Array(n + 1).fill(Infinity);
    dp[0] = 0;
    for (let i = 0; i < n; i++) {
        if (dp[i] === Infinity) continue;
        let node = 0;
        for (let j = i; j < n; j++) {
            if (!ch[node].has(target[j])) break;
            node = ch[node].get(target[j]);
            if (cost[node] < Infinity)
                dp[j + 1] = Math.min(dp[j + 1], dp[i] + cost[node]);
        }
    }
    return dp[n] === Infinity ? -1 : dp[n];
};
